--
-- Структура таблицы `oc_information_description`
--

CREATE TABLE `oc_information_description` (
  `information_id` int(11) NOT NULL,
  `language_id` int(11) NOT NULL,
  `title` varchar(64) NOT NULL,
  `description` text NOT NULL,
  `meta_title` varchar(255) NOT NULL,
  `meta_h1` varchar(255) NOT NULL,
  `meta_description` varchar(255) NOT NULL,
  `meta_keyword` varchar(255) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

--
-- Дамп данных таблицы `oc_information_description`
--

INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_h1`, `meta_description`, `meta_keyword`) VALUES
(6, 1, 'Информация о доставке', '&lt;p&gt;&lt;span style=&quot;font-size:11.0pt;line-height:115%;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;;\r\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;color:black;\r\nmso-ansi-language:RU;mso-fareast-language:EN-US;mso-bidi-language:AR-SA&quot;&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot; class=&quot;docData;DOCY;v5;1563;&quot;&gt;Первое правило нашего магазина ДЕЛИКАТНОЕ отношение и АНОНИМНАЯ доставка! Заказ будет упакован в НЕПРОЗРАЧНЫЙ, ПЛОТНЫЙ пакет или картонную коробку без указания названия магазина и содержимого.&lt;/span&gt;&lt;br&gt;\r\n&lt;br&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot; class=&quot;docData;DOCY;v5;2233;&quot;&gt;Курьеры и работники почты не знают о содержимом доставляемых посылок.&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&lt;br&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Мы уважаем потребности каждого нашего клиента! Быстро и КОНФИДЕНЦИАЛЬНО доставим ваш заказ по всей России!&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&lt;br&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Специально для вас мы работаем без выходных и праздничных дней и осуществляем доставку в любой календарный день для максимального удобства и комфорта!&lt;/span&gt;&lt;br&gt;\r\n&lt;br&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot; class=&quot;docData;DOCY;v5;1857;&quot;&gt;При заказе от 2000 рублей доставка по городу Кургану осуществляется бесплатно, при заказе от 4000 рублей доставка по Курганской области осуществляется бесплатно.&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&lt;br&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;В остальных случаях доставка осуществляется за счёт клиента:&lt;/span&gt;&lt;br&gt;\r\n&lt;br&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot; class=&quot;docData;DOCY;v5;1861;&quot;&gt;- Доставка Курьером по городу Курган - 250-300 рублей, при заказе товаров на сумму от&amp;nbsp; 2500 рублей, курьерская доставка по городу Кургану – БЕСПЛАТНО.&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&lt;br&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Сроки доставки: от 1-го часа (доставка производится стремительно быстро).&lt;/span&gt;&lt;br&gt;\r\n&lt;br&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot; class=&quot;docData;DOCY;v5;2163;&quot;&gt;- &lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Самовывоз&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt; из магазина &quot;Адам и Ева&quot;: Заозерный, 5 микрорайон, 35а.&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&lt;br&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp; ул. Невежина, &lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;д.3, стр.&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;10, ТРЦ «&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Рио&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;», 1 этаж&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size:11.0pt;line-height:115%;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;;\r\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;color:black;\r\nmso-ansi-language:RU;mso-fareast-language:EN-US;mso-bidi-language:AR-SA&quot;&gt;&lt;br&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot; class=&quot;docData;DOCY;v5;2179;&quot;&gt;- &lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Транспортная компания&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&lt;br&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;У&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;кажите в комментарии город и ваш адрес, наш менеджер подберёт ближайший пункт выдачи и свяжется с Вами (от 4000 рублей бесплатная доставка по России, до 4000 рублей уточните стоимость у нашего менеджера)&lt;/span&gt;&lt;br&gt;\r\n&lt;br&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot; class=&quot;docData;DOCY;v5;2604;&quot;&gt;Вы можете быть уверены в сохранности заказанного товара и в полной конфиденциальности данных. Мы отправляем все заказы в специальных плотных картонных коробах,&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;которые гарантируют безопасную транспортировку любых грузов на любые расстояния. Отправление осуществляется от физического лица, без указания названия магазина.&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;&lt;br&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Работники почты не знают о содержимом доставляемых посылок. &lt;/span&gt;&lt;span style=&quot;font-family: Arial; font-size: 11pt;&quot;&gt;Точную стоимость доставки Вам сообщит менеджер, можете уточнить стоимость заранее).&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', '', '', '', ''),
(3, 1, 'Политика безопасности', '&lt;h4 style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;Администрация Сайта осуществляет обработку персональных данных пользователя в целях исполнения обязательств перед пользователем в рамках размещенных на Сайте публичных оферт (далее – оферта) – обязательства по предоставлению доступа к различным корпоративным разделам Сайта, специальным корпоративным программам, обработки информации о порядке взаимодействия пользователя с Сайтом, для целей произведения пользователю оплат выполненных работ/оказанных услуг, исполнению обязательств налогового агента в соответствии с требованиями действующего законодательства, допуска пользователя к участию в конкурсах и распределения призового фонда, - либо в целях предоставления пользователю доступа к программам и сервисам Сайта в рамках Пользовательского соглашения.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;В силу статьи 6 Федерального закона от 27.07.2006 г. № 152-ФЗ «О персональных данных» согласие пользователя на обработку его персональных данных как обязательное условие обработки персональных данных обязательно. Предоставление персональных данных пользователем осуществляется в добровольном порядке. Получение личного согласия Пользователя на обработку (включая хранение) персональных данных производится в порядке личного непосредственного заполнения пользователем электронного опросного листа на Сайте при регистрации пользователя.&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;\r\n', '', '', '', ''),
(3, 2, 'Privacy Policy', '&lt;p&gt;\r\n	Privacy Policy&lt;/p&gt;\r\n', '', '', '', ''),
(5, 2, 'Terms &amp; Conditions', '&lt;p&gt;\r\n	Terms &amp;amp; Conditions&lt;/p&gt;\r\n', '', '', '', ''),
(5, 1, 'Условия соглашения', '&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Условия соглашения:&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;На все товары имеющие функцию вибрации или другие электрические движущиеся части ( например: вибраторы, вагины с вибрацией, вибро яйца и т.д.) в магазине «Адам и Ева» предоставляется&amp;nbsp;&lt;strong&gt;гарантия 14&amp;nbsp; дней&lt;/strong&gt;&amp;nbsp;со дня покупки на исправность работы.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Это означает, что приобретая товар в магазине «Адам и Ева», в течение 14 последующих дней выявилась неисправность по причине брака,&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: &amp;quot;Open Sans&amp;quot;; font-size: 11pt;&quot;&gt;то Мы предлагаем Вам следующие варианты:&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;-обменять товар на аналогичный;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;-обменять товар на любую продукцию нашего магазина (возможно стоимостью выше с доплатой);&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;- вернем полную стоимость товара по чеку.&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;Возврат производится только после проведения экспертизы ( на наличие заводского брака ) магазином «Адам и Ева».&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;*Чтобы оформить возврат товара необходимо заполнить форму&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: bold; text-decoration: underline; color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;«Условия возврата»:&lt;/span&gt;&lt;/p&gt;&lt;ol style=&quot;margin-top: 0pt; margin-bottom: 0pt;&quot;&gt;&lt;li style=&quot;list-style-type: decimal;&quot;&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;Причина возврата (описание);&lt;/span&gt;&lt;/p&gt;&lt;/li&gt;&lt;li style=&quot;list-style-type: decimal;&quot;&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;Прикрепите фото ( пример до 3-х изображений);&lt;/span&gt;&lt;/p&gt;&lt;/li&gt;&lt;li style=&quot;list-style-type: decimal;&quot;&gt;&lt;p style=&quot;margin-bottom: 13.3333px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;Укажите E-mail для обратной связи.&lt;/span&gt;&lt;/p&gt;&lt;/li&gt;&lt;/ol&gt;&lt;p style=&quot;margin-bottom: 13.3333px; margin-left: 48px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;Ваше обращение будет рассмотрено в течение 3(трёх) рабочих дней и ответ направлен на E-mail в виде письма.&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span id=&quot;mail-clipboard-id-71863271456575144079276595309438&quot; style=&quot;color: rgb(0, 0, 0); font-family: Arial, Verdana, sans-serif; font-size: 13px; white-space: pre;&quot;&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 13.3333px; margin-left: 48px; line-height: 1.15;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 11pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;*&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 9pt; font-family: &amp;quot;Open Sans&amp;quot;;&quot;&gt;доставка возвращаемого товара производится за счёт клиента.&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Товар магазина «Адам и Ева» принадлежит к группе товаров личной гигиены, которые, согласно Ст. 25 П. 1 закону «О защите прав потребителей»&amp;nbsp;&lt;strong&gt;возврату и обмену не подлежат&lt;/strong&gt;.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Закон о защите прав потребителей:&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Ст. 25 п.1 Право потребителя на обмен товара надлежащего качества:&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Потребитель вправе обменять непродовольственный товар надлежащего качества на аналогичный товар у продавца, у которого этот товар был приобретен, если указанный товар не подошел по форме, габаритам, фасону, расцветке, размеру или комплектации.&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Перечень товаров,&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;strong&gt;&lt;i&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;не подлежащих обмену и возврату&lt;/span&gt;&lt;/i&gt;&lt;/strong&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&amp;nbsp;по основаниям, указанным в настоящей статье, утверждается Правительством Российской Федерации&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Перечень: (Постановление Правительства РФ от 19 января 1998 г. N 55)&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;п.1 . Товары для профилактики и лечения заболеваний в домашних условиях (предметы санитарии и гигиены из металла, резины, текстиля и других материалов...&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;п. 2 Предметы личной гигиены (зубные щетки, расчески, заколки, бигуди для волос, парики, шиньоны и другие аналогичные товары)&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;п.3 Парфюмерно-косметические товары&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;п.5 Швейные и трикотажные изделия (изделия швейные и трикотажные бельевые, изделия чулочно-носочные)&lt;/span&gt;&lt;/em&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&amp;nbsp;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin: 9.6pt 0cm; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 10.5pt; font-family: Arial, sans-serif; color: black;&quot;&gt;Это означает, что если Вы, купив в нашем магазине товар данной категории надлежащего качества, решите, что он Вас не устраивает по его ранее заявленным потребительским характеристикам, магазин не сможет у Вас принять его обратно или заменить на аналогичный даже при условии целостности упаковки и наличия сопроводительных документов.&lt;/span&gt;&lt;/p&gt;\r\n', '', '', '', ''),
(4, 1, 'О нас', '&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Наши офлайн магазины находятся в городе Курган. Мы профессионалы и работаем более 10 лет!&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Магазин «Адам и Ева» - это команда специалистов работающих над укреплением семьи и&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;брака, а так же развитием максимально комфортных отношений с заботой о здоровье!&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Первое правило нашего магазина ДЕЛИКАТНОЕ отношение и&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;АНОНИМНАЯ доставка!&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Заказ будет упакован в НЕПРОЗРАЧНЫЙ, ПЛОТНЫЙ пакет или&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;картонную почтовую коробку без указания названия магазина и&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;содержимого.&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Курьеры и работники почты не знают о содержимом&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;доставляемых посылок.&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Мы уважаем потребности каждого нашего клиента! Быстро и&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;КОНФИДЕНЦИАЛЬНО доставим ваш заказ по всей России!&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Специально для вас мы работаем без выходных и праздничных&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;дней для Вашего&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;максимального удобства и комфорта!&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Высококвалифицированную консультацию Вы сможете получить online или по телефону, а так&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;же в наших магазинах совершенно бесплатно. У нас Вы обязательно найдёте то, что давно искали!&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Мы работаем для вас!&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Предложения и замечания по работе online магазина просьба направлять по форме обратной связи или&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;по телефонным номерам указанным в контактной информации. Всего Вам доброго! Любите и будьте любимыми!&lt;/span&gt;&lt;br style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 14px;&quot;&gt;Команда магазина «Адам и Ева»&lt;/span&gt;&lt;br&gt;&lt;/p&gt;\r\n', '', '', '', ''),
